import{z as A,x as d,o as r,c as B,q as s,j as i,D as E,d as n,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"多值依赖与 4NF","description":"","frontmatter":{"title":"多值依赖与 4NF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mvd-4nf.md","filePath":"cs/mvd-4nf.md","lastUpdated":1791063341000}'),p={name:"cs/mvd-4nf.md"};function F(D,a,m,N,h,f){const t=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=s('<h1 id="多值依赖与-4nf" tabindex="-1">多值依赖与 4NF <a class="header-anchor" href="#多值依赖与-4nf" aria-label="Permalink to &quot;多值依赖与 4NF&quot;">​</a></h1><div class="epigraph"><p>多值依赖说两套独立事实被塞进同一键下：元组必须交叉出现。4NF 要求这种独立乘积被拆开。</p><footer>—— 据 Fagin, Multivalued Dependencies and a New Normal Form, TODS 1977；Beeri, Fagin, Howard；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/lossless-dependency-preserving">上一课</a>处理 FD 下的无损与保持。本课不重做 chase。缺口是：即使没有非平凡 FD，一张表仍可被迫存笛卡尔积。课程安排独立、讲师独立，键是课程，却放在同一关系里，行数是两套列表的乘积。多值依赖（MVD）命名这件事；4NF 沿 MVD 分解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MVD \\(X \\twoheadrightarrow Y\\)（在 \\(U\\) 上）大致：给定 \\(X\\)，属性集 \\(Y\\) 与 \\(U-X-Y\\) 独立——合法实例必须包含 \\(Y\\) 值与其余属性值的全部组合。FD 是 MVD 的特例（\\(Y\\) 被 \\(X\\) 唯一决定时组合塌缩）。缺口是识别「独立重复组」，不是再定义 3NF。</p><p>4NF：每个非平凡 MVD \\(X \\twoheadrightarrow Y\\)，\\(X\\) 都是超键。分解：把 \\(R\\) 拆成 \\(XY\\) 与 \\(X(U-Y)\\)，无损（对 MVD）。这与 BCNF 切开形状相似，依据从 FD 换成 MVD。</p><p><span class="marginnote">符号 \\(X \\twoheadrightarrow Y\\) 读作「X 多值决定 Y」：给定一个 X 值，Y 取一整组值，而且这组值与剩下的属性互不干涉。可以把它想象成两张各自独立的选课清单被强行装订进了同一本册子——FD 说「一个 X 只配一个 Y」，MVD 说「一个 X 配一整组 Y，组与组自由组合」。</span></p><p><span class="marginnote">数字实例：某课程有 3 本教材、2 位助教，业务上二者独立。合法的原始事实只有 \\(3+2=5\\) 条，但同一张表里必须存满 \\(3 \\times 2=6\\) 行——多出的 1 行就是交叉乘积强迫出来的组合。教材 100 本、助教 100 位时，200 条事实会膨胀成 10000 行。</span></p><p><span class="marginnote">Fagin 1977。补规则与合并规则构成 MVD 公理（与 Armstrong 一起）。本课不默写全部公理，只要求：独立乘积是模式错误，不是「数据恰好这么多」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发现：若业务上「给定课程，教材列表与助教列表无关」，却存在于同一表，则有 MVD。分解后各存一列多值事实，查询要用连接恢复组合——这是正确的组合，不是虚假元组。若业务上并非独立（教材决定助教），则不是 MVD，不能拆。</p><p>与 1NF：1NF 禁止表中表；把多值拆成多行后仍可能留在一张宽表里造成乘积。4NF 是 1NF 之后、针对独立多值的下一刀。</p>',12)),(r(),i(o,null,{default:E(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E9%94%AE%20X%22%5D%20--%3E%20Y%5B%22Y%20%E7%9A%84%E5%A4%9A%E5%80%BC%E5%88%97%E8%A1%A8%22%5D%0A%20%20KEY%20--%3E%20Z%5B%22Z%20%E7%9A%84%E5%A4%9A%E5%80%BC%E5%88%97%E8%A1%A8%22%5D%0A%20%20Y%20--%3E%20PROD%5B%22%E4%BA%A4%E5%8F%89%E4%B9%98%E7%A7%AF%E8%A1%8C%22%5D%0A%20%20Z%20--%3E%20PROD%0A%20%20PROD%20--%3E%20SPLIT%5B%224NF%3A%20XY%20%E4%B8%8E%20XZ%20%E4%B8%A4%E8%A1%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"BCNF 过、4NF 不过：没有非平凡 FD，但仍有非平凡 MVD。主干范式课故意不把 4NF 写进必做；进阶在此补层。连接恢复的是独立组合的全积，与业务「确实独立」一致。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"初学者容易以为 BCNF 达标就高枕无忧——实际上 BCNF 只检查函数依赖，而两套独立列表之间可以完全没有 FD，表照样在偷偷存笛卡尔积。这就是「BCNF 过、4NF 不过」的含义：范式越高一层，检查的依赖种类越广。")],-1)),(r(),i(o,null,{default:E(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22%E5%8E%9F%E8%A1%A8%20R%EF%BC%88%E8%AF%BE%E7%A8%8B%2C%20%E6%95%99%E6%9D%90%2C%20%E5%8A%A9%E6%95%99%EF%BC%89%22%5D%20--%3E%20P1%5B%22%E6%8A%95%E5%BD%B1%20R1%EF%BC%88%E8%AF%BE%E7%A8%8B%2C%20%E6%95%99%E6%9D%90%EF%BC%89%22%5D%0A%20%20R%20--%3E%20P2%5B%22%E6%8A%95%E5%BD%B1%20R2%EF%BC%88%E8%AF%BE%E7%A8%8B%2C%20%E5%8A%A9%E6%95%99%EF%BC%89%22%5D%0A%20%20P1%20--%3E%20J%5B%22%E6%8C%89%E8%AF%BE%E7%A8%8B%E5%81%9A%E8%87%AA%E7%84%B6%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20P2%20--%3E%20J%0A%20%20J%20--%3E%20OK%5B%22%E6%81%A2%E5%A4%8D%E5%87%BA%E7%9A%84%E7%BB%84%E5%90%88%20%3D%20%E5%85%A8%E9%83%A8%E5%90%88%E6%B3%95%E8%A1%8C%22%5D%0A%20%20J%20--%3E%20NJ%5B%22%E7%8B%AC%E7%AB%8B%E6%80%A7%E4%BF%9D%E8%AF%81%E6%97%A0%E8%99%9A%E5%81%87%E5%85%83%E7%BB%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>保持性对 MVD 更细，本课不把 MVD 保持当必考算法。实践：识别独立多值并拆表，约束用键。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 5NF（投影-连接依赖）——下一课。也不把 JSON 数组列当成自动 4NF 违反；嵌套是另一数据模型，是否独立仍是语义问题。NULL 与 MVD 的理论更窄，工程上先把列表拆成关系。</p><p>后课默认：独立多值事实分表。5NF 处理「三次投影才能无损」的连接依赖，更稀，但反规范化会反过来走。</p><p>MVD 不是「多值属性」的同义词；它是合法实例上的交叉条件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MVD 刻画键下两套独立列表的交叉乘积。</li><li>4NF 沿非平凡 MVD 切开，X 须为超键。</li><li>5NF 与反规范化下一课：何时再连回去。</li><li>出处：Fagin 1977；Beeri, Fagin, Howard；Ramakrishnan and Gehrke。</li></ul>',7))])}const u=A(p,[["render",F]]);export{C as __pageData,u as default};
